reps_s = 1000
rng_s = np.random.default_rng(SEED)
res_s = {c: {"случайная": [], "страт.": []} for c in cols}
for _ in range(reps_s):
    rs_ = df.sample(n=n_s, random_state=int(rng_s.integers(1e9)))
    ss_ = stratified_sample(df, n_s, int(rng_s.integers(1e9)))
    for c in cols:
        res_s[c]["случайная"].append(rs_[c].mean())
        res_s[c]["страт."].append(ss_[c].mean())

for c in cols:
    print(c, ": std средних, случайная =", round(np.std(res_s[c]["случайная"], ddof=1), 5),
          ", стратифицированная =", round(np.std(res_s[c]["страт."], ddof=1), 5))
print("ИТОГ разброс средних:", {c: {k: round(np.std(v,ddof=1),5) for k,v in res_s[c].items()} for c in cols})
